#include <stdio.h>
typedef int (*Operation)(int,int);
static int add_values(int a,int b){return a+b;}
static int subtract(int a,int b){return a-b;}
int main(void) {
    int op,a,b;
    if(scanf("%d%d%d",&op,&a,&b)!=3 || op<0 || op>1) return 1;
    Operation operations[] = {add_values, subtract};
    printf("%d\n", operations[op](a,b));
    return 0;
}
